import hashlib
VER=hashlib.md5(open('style.css','rb').read()+open('main.js','rb').read()).hexdigest()[:8]
def page(fn,title,body):
  nav=''.join(f'<li><a href="{f}" class="{'active ' if f==fn else ''}{'zk-nav' if f=='zukunft.html' else ''}">{SHORT.get(f,t)}</a></li>' for f,t in PAGES)
  return f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title} · neXmind Academy</title><meta name="description" content="Qigong, Energiearbeit und ganzheitliche Themen – neXmind Academy">
<link rel="stylesheet" href="fonts/fonts.css">
<link rel="stylesheet" href="style.css?v={VER}"><link rel="icon" type="image/svg+xml" href="favicon.svg"></head><body>
<header><div class="wrap nav"><a class="brand" href="index.html"><img src="logo.svg" alt="neXmind Academy" class="nxlogo"><span class="sub">Spiritualität · Gesundheit · Zukunft</span></a>
<nav><button class="burger" aria-label="Menü"><span></span><span></span></button><ul>{nav}</ul></nav></div></header>
<main>{body}</main>{MEADOW}
<footer><div class="wrap"><div class="cols"><div><a class="brand" href="index.html"><img src="logo-light.svg" alt="neXmind Academy" class="nxlogo"></a>
<p style="margin-top:1rem;max-width:380px">„neXmind Academy inspires lifelong well-being, wisdom, peace, compassion, joy and enlightenment.“</p></div>
<div><h4>Seiten</h4>{''.join(f'<a href="{f}">{t}</a>' for f,t in PAGES)}</div>
<div><h4>Kontakt</h4><p>Sigmar Schnur<br>Waagner-Biro-Str. 126/1/30<br>8020 Graz, Österreich<br><a href="mailto:info@nxmind.at">info@nxmind.at</a></p></div></div>
<p class="disclaimer"><strong>Hinweis:</strong> Die hier beschriebenen Übungen und Angebote dienen dem allgemeinen Wohlbefinden und der Entspannung. Sie ersetzen keine ärztliche oder psychotherapeutische Diagnose und Behandlung; es werden keine Heilversprechen gegeben. Bei gesundheitlichen Beschwerden wende dich bitte an Ärztin oder Arzt.</p><p class="legal-links" style="margin-top:.8rem"><a href="impressum.html">Impressum</a> · <a href="datenschutz.html">Datenschutz</a></p></div></footer>
<script src="main.js?v={VER}"></script></body></html>'''
def head(eb,h,p):
  return f'<section class="page-head"><svg class="ring" viewBox="0 0 600 600" fill="none"><circle cx="300" cy="300" r="240" stroke="#b49a5e" stroke-width=".8"/><circle cx="300" cy="300" r="180" stroke="#a9bfa8" stroke-width=".8"/></svg><div class="wrap reveal"><span class="eyebrow">{eb}</span><h1>{h}</h1><p>{p}</p></div></section>'
P=lambda t:f'<p class="placeholder">{t}</p>'

def V(id,t): return f'<div class="video reveal"><iframe src="https://player.vimeo.com/video/{id}?dnt=1&title=0&byline=0&portrait=0" title="{t}" loading="lazy" allow="fullscreen; picture-in-picture" allowfullscreen></iframe><span>Video: {t} · Feng Huang Yuan (Vimeo)</span></div>'
EXN=[
('bell','Bronzeglocke','Feng Huang Bronzeglocke · Basisübung','Eine stille, sich selbst regulierende Übung mit langer Überlieferung – der Legende nach brachte Bodhidharma sie von Indien nach China; Großmeister Datong Shizun hat sie energetisch erhöht. Sie ist leicht zu lernen und lässt sich fast überall üben.',
 [('Zweck','Sammlung, innere Ruhe und ein freier Fluss des Qi; ein stabiles Gefühl, „in sich zu stehen“.'),('Haltung','Im Stehen, Sitzen oder Liegen (insgesamt sechs Positionen). Wirbelsäule aufgerichtet, Schultern sinken, Kiefer locker, Blick weich oder Augen geschlossen.'),('Ablauf','Ankommen und die Haltung einnehmen · Aufmerksamkeit sanft nach innen richten · die Vorstellung einer schützenden Glocke um den Körper · in der Stille verweilen und den Körper sich selbst regulieren lassen · langsam zurückkommen, Hände reiben, Gesicht ausstreichen.'),('Atmung','Natürlich und ruhig durch die Nase, nichts erzwingen; der Atem wird mit der Zeit von selbst tiefer.'),('Dauer','Zum Einstieg 10–15 Minuten, später 30 Minuten oder länger, gern täglich zur gleichen Zeit.'),('Hinweise','Nicht direkt nach schweren Mahlzeiten üben. Spontane kleine Bewegungen oder Wärme sind normal – nichts festhalten. Die genaue Anleitung der sechs Positionen gibt es im Kurs.')],None),
('hand','Heilige Hände','Feng Huang Heilige Hände · Aufbauübung','Die Aufbauübung zur Bronzeglocke. Über Akupunkturpunkte an den Händen wird das Qi angeregt und nach außen gelenkt – zur Stärkung der eigenen Kräfte und als Grundlage, anderen Menschen energetisch beizustehen.',
 [('Zweck','Die Wirkung der Bronzeglocke vertiefen, Wärme und Energie in den Händen spüren, achtsame Berührung lernen.'),('Haltung','Aufrecht stehend oder sitzend, Knie weich, Ellenbogen leicht vom Körper gelöst, Hände entspannt vor dem Unterbauch.'),('Ablauf','Mit einigen Minuten Bronzeglocke beginnen · die Handpunkte nach der im Kurs gelehrten Methode aktivieren · die Handflächen einander zuwenden und den „Energieball“ spüren · Qi zum eigenen Körper oder – nach Anleitung – zu einem Gegenüber lenken · zum Abschluss sammeln am Unterbauch.'),('Atmung','Ruhig und weich; beim Sammeln etwas länger ausatmen.'),('Dauer','15–20 Minuten; vorher die Bronzeglocke als Basis.'),('Hinweise','Setzt die Bronzeglocke voraus und wird nur im Kurs vollständig vermittelt. Arbeit mit anderen ersetzt keine medizinische Behandlung.')],None),
('word','Die vier wahren Worte','Wahre Worte der himmlischen Liebe · „Seelensutra“','„Ich liebe dich. Es tut mir leid. Ich bitte um Vergebung. Danke.“ Vier Sätze, mit offenem Herzen gesprochen – eine Praxis der Versöhnung mit sich selbst, anderen Menschen und allem Lebendigen.',
 [('Zweck','Beziehungen klären, Belastendes loslassen, Dankbarkeit und Liebe stärken. „Es tut mir leid“ und „Ich bitte um Vergebung“ lassen los, „Ich liebe dich“ und „Danke“ nehmen Helles auf.'),('Haltung','Aufrecht stehend oder sitzend, Herz offen, Gesicht entspannt.'),('Ablauf','Es gibt eine stille und eine bewegte Form. In der bewegten Form begleitet je eine einfache Armbewegung jedes der vier Worte; die Worte werden laut und aufrichtig rezitiert und mehrfach wiederholt. Man kann sie einem Menschen, einem Körperteil, einer Situation oder sich selbst widmen.'),('Atmung','Sprechen im Ausatmen, natürliches Einatmen zwischen den Sätzen.'),('Dauer','Wenige Minuten bis zu einer halben Stunde; die bewegte, laut gesprochene Form gilt als die wirksamste.'),('Hinweise','Wichtiger als die Anzahl ist die Aufrichtigkeit. Die Übung lässt sich gut in den Alltag einbauen.')],('661019482','Worte der Himmlischen Liebe')),
('run','Dimensionslauf','„Wir joggen in eine höhere Dimension“','Ein Lauf auf der Stelle, der viele überrascht: Trotz Bewegung kommen selbst Untrainierte kaum außer Atem und fühlen sich danach frisch. Er braucht nur wenig Platz und eignet sich für Jung und Alt.',
 [('Zweck','Herz und Lunge sanft trainieren, Haltung verbessern, den Körper beleben – als regelmäßige Fitness- und Wellnessübung.'),('Haltung','Aufrecht, Blick geradeaus, Schultern locker, Arme schwingen frei; fester, aber leichter Stand.'),('Ablauf','Locker auf der Stelle beginnen · den im Video gezeigten Bewegungsvarianten folgen, jede mit eigener Wirkung · Tempo so wählen, dass man sich noch unterhalten könnte · langsam ausklingen lassen und kurz still nachspüren.'),('Atmung','Frei und rhythmisch durch die Nase; bei Atemnot Tempo reduzieren.'),('Dauer','Das Übungsvideo dauert gut 7 Minuten – ideal als tägliche Einheit.'),('Hinweise','Bei Herz-, Gelenk- oder Kreislaufproblemen vorher ärztlich abklären und behutsam beginnen.')],('661017277','Joggen – Dimensionslauf')),
('walk','Himmlischer Spaziergang','Eine Reise durch den Kosmos','Eine sehr einfache Übung, die man auch zwischendurch am Arbeitsplatz machen kann: In der Vorstellung strömt farbiges Licht der fünf Planeten, entsprechend den fünf Elementen, in die Organe und nährt Körper und Seele.',
 [('Zweck','Entspannung, ein leichtes, wohliges Körpergefühl, Reinigung von Belastendem – auch für die Atmosphäre des Raumes.'),('Haltung','Beliebig: stehend, sitzend oder gehend; die Augen können offen bleiben.'),('Ablauf','Den „himmlischen Regen“ von oben einladen · das Licht durch die inneren Organe fließen lassen · Belastendes über die Fußsohlen (Punkt Yongquan) in die Erde abgeben · „Das Licht ist in meinem Körper, mein Körper ist im Licht.“'),('Atmung','Natürlich, ohne Technik.'),('Dauer','Kurz oder lang, jederzeit – schon wenige Minuten tun gut.'),('Hinweise','Lässt sich sogar beim Musikhören oder Spazierengehen üben.')],None),
]

